-- Preserve the product rule as data, not application logic: the free country policy is a generic Free Plan policy.
UPDATE subscription_policies SET plan_code='free',subscription_class='exempt',can_create_missions=1,can_create_drivers=1,can_share_foryou=0,can_request_foryou=0,can_share_network=1,can_accept_network=1 WHERE country_code='AF' AND subject_type='tenant_admin' AND plan_code='starter' AND billing_mode='free';
INSERT OR IGNORE INTO subscription_policies (subject_type,country_code,plan_code,billing_mode,billing_period_days,grace_days,verification_required,max_drivers,max_missions_period,max_storage_mb,public_missions_enabled,subscription_class,can_create_missions,can_create_drivers,can_share_foryou,can_request_foryou,can_share_network,can_accept_network) VALUES ('tenant_admin','AF','free','free',30,0,1,5,200,1024,0,'exempt',1,1,0,0,1,1);
INSERT OR IGNORE INTO subscription_policies (subject_type,country_code,plan_code,billing_mode,billing_period_days,grace_days,verification_required,max_drivers,max_missions_period,max_storage_mb,public_missions_enabled,subscription_class,can_create_missions,can_create_drivers,can_share_foryou,can_request_foryou,can_share_network,can_accept_network) SELECT 'tenant_admin',cc.code,p.plan_code,p.billing_mode,p.billing_period_days,p.grace_days,p.verification_required,p.max_drivers,p.max_missions_period,p.max_storage_mb,p.public_missions_enabled,'eligible',p.can_create_missions,p.can_create_drivers,p.can_share_foryou,p.can_request_foryou,p.can_share_network,p.can_accept_network FROM country_catalog cc JOIN subscription_policies p ON p.subject_type='tenant_admin' AND p.country_code='ZZ' AND p.plan_code IN ('starter','business') WHERE cc.code<>'AF' AND cc.active=1;
INSERT OR IGNORE INTO subscription_policies (subject_type,country_code,plan_code,billing_mode,billing_period_days,grace_days,verification_required,max_drivers,max_missions_period,max_storage_mb,public_missions_enabled,subscription_class,can_create_missions,can_create_drivers,can_share_foryou,can_request_foryou,can_share_network,can_accept_network) SELECT 'independent_executor',cc.code,'executor','free',30,0,1,NULL,100,NULL,0,'exempt',0,0,0,1,0,1 FROM country_catalog cc WHERE cc.active=1;
ALTER TABLE verification_profiles ADD COLUMN declared_country_code TEXT;
ALTER TABLE verification_profiles ADD COLUMN verified_country_code TEXT;
UPDATE verification_profiles SET declared_country_code=COALESCE(declared_country_code,country_code,'ZZ') WHERE declared_country_code IS NULL;
UPDATE verification_profiles SET verified_country_code=CASE WHEN review_status='approved' THEN COALESCE(country_code,'ZZ') ELSE verified_country_code END WHERE verified_country_code IS NULL;
CREATE TABLE verification_checks_new (id INTEGER PRIMARY KEY AUTOINCREMENT, profile_id INTEGER NOT NULL, check_type TEXT NOT NULL CHECK(check_type IN ('email','phone','company','country','balm','identity')), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','verified','rejected','not_required')), method TEXT, verified_at TEXT, reviewer_note TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(profile_id) REFERENCES verification_profiles(id) ON DELETE CASCADE, UNIQUE(profile_id,check_type));
INSERT INTO verification_checks_new(id,profile_id,check_type,status,method,verified_at,reviewer_note,updated_at) SELECT id,profile_id,check_type,status,method,verified_at,reviewer_note,updated_at FROM verification_checks;
DROP TABLE verification_checks;
ALTER TABLE verification_checks_new RENAME TO verification_checks;
CREATE INDEX IF NOT EXISTS idx_verification_checks_profile ON verification_checks(profile_id,check_type,status);
INSERT OR IGNORE INTO verification_checks(profile_id,check_type,status,method,verified_at,reviewer_note,updated_at) SELECT id,'country',CASE WHEN review_status='approved' THEN 'verified' ELSE 'pending' END,CASE WHEN review_status='approved' THEN 'legacy_approved' ELSE 'platform_review' END,CASE WHEN review_status='approved' THEN reviewed_at ELSE NULL END,CASE WHEN review_status='approved' THEN 'Country accepted under the pre-country-review approval.' ELSE NULL END,CURRENT_TIMESTAMP FROM verification_profiles;

-- Keep the profile country_code aligned with the declared value for compatibility; verified_country_code is the authority after review.
UPDATE verification_profiles SET country_code=COALESCE(declared_country_code,country_code,'ZZ') WHERE country_code IS NULL;
